<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { apiDelete, apiGet, apiPost, apiPostForm, apiPut, type ApiError } from './api/client'
import TenantLogInspector from './TenantLogInspector.vue'
import { confirmDialog } from './appDialog'

type SessionState={accessToken:string;refreshToken:string;userEmail:string}
type TenantRow={id:string;name:string;slug:string;status:string}
type Section='general'|'access'|'experience'|'logs'|'lifecycle'
type TenantManagementSnapshot={tenant:{id:string;name:string;slug:string;status:string;timezone:string;primary_hostname?:string|null;created_at?:string|null};principal_admin?:{id:string;email:string;display_name:string;is_active:boolean;created_at?:string|null}|null;principal_admin_error?:{type:string;message:string}|null;slug_editable:boolean;slug_note:string}
type AdminExperienceVersion={id:string;html:string;metadata?:Record<string,any>;bindings_values?:Record<string,any>;theme?:Record<string,any>}
type AdminExperiencePage={page?:{surface:string;template_key?:string|null};version?:AdminExperienceVersion|null}|null
type AdminExperienceSnapshot={experience?:{pages?:Array<{surface:string;enabled:boolean;template_key?:string|null}>};branding?:any}
type ExperiencePolicy={level:'blocked'|'basic'|'design'|'full'|'developer';apply_theme_to_console:boolean}
type ResendAccessResult={snapshot:TenantManagementSnapshot;delivery:{delivered:boolean;error_code?:string|null;message?:string|null;recipient:string;login_url:string};temporary_password?:string|null}

const storageKey='scheduler-pro-admin-session'
const isOpen=ref(false)
const authenticated=ref(false)
const loading=ref(false)
const errorMessage=ref('')
const successMessage=ref('')
const generatedPassword=ref('')
const tenants=ref<TenantRow[]>([])
const selectedTenantId=ref('')
const snapshot=ref<TenantManagementSnapshot|null>(null)
const tenantName=ref('')
const tenantTimezone=ref('America/Bahia')
const adminEmail=ref('')
const adminDisplayName=ref('')
const adminPassword=ref('')
const section=ref<Section>('general')
const experienceLevel=ref<ExperiencePolicy['level']>('basic')
const experienceThemeConsole=ref(false)
const adminExperienceSurface=ref<'LANDING'|'BOOKING'>('LANDING')
const adminExperiencePage=ref<AdminExperiencePage>(null)
const adminExperienceBindings=ref<Record<string,any>>({})
const adminExperienceTheme=ref<Record<string,any>>({})
const adminExperienceBranding=ref<any>(null)
let sessionTimer:number|undefined

const selectedTenant=computed(()=>tenants.value.find(item=>item.id===selectedTenantId.value)??null)
function session():SessionState|null{const raw=localStorage.getItem(storageKey);if(!raw)return null;try{return JSON.parse(raw) as SessionState}catch{return null}}
function token():string{return session()?.accessToken||''}
function describeError(error:unknown,fallback:string):string{const value=error as Partial<ApiError>;if(value?.message&&value?.code)return `${value.message} (${value.code})`;return value?.message||fallback}
function syncAuthentication():void{authenticated.value=Boolean(token());if(!authenticated.value){isOpen.value=false;snapshot.value=null}}
function applySnapshot(value:TenantManagementSnapshot):void{snapshot.value=value;tenantName.value=value.tenant.name;tenantTimezone.value=value.tenant.timezone||'America/Bahia';adminEmail.value=value.principal_admin?.email||'';adminDisplayName.value=value.principal_admin?.display_name||'';adminPassword.value=''}
async function loadTenants():Promise<void>{tenants.value=await apiGet<TenantRow[]>('/platform/tenants',token());if(!selectedTenantId.value&&tenants.value.length)selectedTenantId.value=tenants.value[0].id}
async function loadExperiencePolicy():Promise<void>{if(!selectedTenantId.value)return;const value=await apiGet<ExperiencePolicy>(`/platform/tenant-management/${selectedTenantId.value}/experience-policy`,token());experienceLevel.value=value.level;experienceThemeConsole.value=Boolean(value.apply_theme_to_console)}
async function loadSnapshot():Promise<void>{snapshot.value=null;generatedPassword.value='';if(!selectedTenantId.value)return;applySnapshot(await apiGet<TenantManagementSnapshot>(`/platform/tenant-management/${selectedTenantId.value}`,token()));await loadExperiencePolicy().catch(()=>undefined)}
async function openManager():Promise<void>{isOpen.value=true;loading.value=true;errorMessage.value='';successMessage.value='';try{await loadTenants();await loadSnapshot()}catch(error){errorMessage.value=describeError(error,'Não foi possível carregar a gestão do tenant.')}finally{loading.value=false}}
async function selectTenant():Promise<void>{loading.value=true;errorMessage.value='';successMessage.value='';generatedPassword.value='';try{await loadSnapshot()}catch(error){errorMessage.value=describeError(error,'Falha ao carregar o tenant selecionado.')}finally{loading.value=false}}
async function saveTenant():Promise<void>{if(!selectedTenantId.value)return;loading.value=true;errorMessage.value='';successMessage.value='';try{const value=await apiPut<TenantManagementSnapshot>(`/platform/tenant-management/${selectedTenantId.value}`,{name:tenantName.value.trim(),timezone:tenantTimezone.value.trim()},token());applySnapshot(value);await loadTenants();successMessage.value='Dados do tenant atualizados.'}catch(error){errorMessage.value=describeError(error,'Falha ao atualizar o tenant.')}finally{loading.value=false}}
async function savePrincipalAdmin():Promise<void>{if(!selectedTenantId.value)return;if(adminPassword.value&&adminPassword.value.length<12){errorMessage.value='A nova senha deve ter no mínimo 12 caracteres.';return}loading.value=true;errorMessage.value='';successMessage.value='';generatedPassword.value='';try{const payload:Record<string,string>={email:adminEmail.value.trim(),display_name:adminDisplayName.value.trim()||'Administrador'};if(adminPassword.value)payload.password=adminPassword.value;const value=await apiPut<TenantManagementSnapshot>(`/platform/tenant-management/${selectedTenantId.value}/principal-admin`,payload,token());const rotated=Boolean(adminPassword.value);applySnapshot(value);successMessage.value=rotated?'Usuário principal atualizado, senha trocada e sessões antigas revogadas.':'Usuário principal do tenant atualizado.'}catch(error){errorMessage.value=describeError(error,'Falha ao atualizar o usuário principal.')}finally{loading.value=false}}
async function resendAccess(generatePassword=false):Promise<void>{if(!selectedTenantId.value)return;if(adminPassword.value&&adminPassword.value.length<12){errorMessage.value='A nova senha deve ter no mínimo 12 caracteres.';return}if(generatePassword&&adminPassword.value){errorMessage.value='Limpe o campo “Nova senha” para gerar automaticamente uma senha temporária.';return}loading.value=true;errorMessage.value='';successMessage.value='';generatedPassword.value='';try{const payload:Record<string,unknown>={email:adminEmail.value.trim(),display_name:adminDisplayName.value.trim()||'Administrador',generate_password:generatePassword};if(adminPassword.value)payload.password=adminPassword.value;const result=await apiPost<ResendAccessResult>(`/platform/tenant-management/${selectedTenantId.value}/principal-admin/resend-access`,payload,token());applySnapshot(result.snapshot);generatedPassword.value=result.temporary_password||'';if(result.delivery.delivered){successMessage.value=`Dados de acesso enviados para ${result.delivery.recipient}.`}else{errorMessage.value=`As alterações foram salvas, mas o e-mail não foi entregue${result.delivery.error_code?` (${result.delivery.error_code})`:''}. ${result.delivery.message||''}`.trim()}}catch(error){errorMessage.value=describeError(error,'Falha ao reenviar o acesso do tenant.')}finally{loading.value=false}}
async function loadAdminExperience():Promise<void>{if(!selectedTenantId.value)return;try{const snap=await apiGet<AdminExperienceSnapshot>(`/platform/tenant-management/${selectedTenantId.value}/experience`,token());adminExperienceBranding.value=snap.branding||null;await loadAdminExperiencePage()}catch(error){errorMessage.value=describeError(error,'Falha ao carregar experiência do tenant.')}}
async function loadAdminExperiencePage():Promise<void>{if(!selectedTenantId.value)return;const value=await apiGet<AdminExperiencePage>(`/platform/tenant-management/${selectedTenantId.value}/experience/pages/${adminExperienceSurface.value}`,token());adminExperiencePage.value=value;adminExperienceBindings.value={...(value?.version?.bindings_values||{})};adminExperienceTheme.value={...(value?.version?.theme||{})}}
async function saveAdminExperience(publish=false):Promise<void>{if(!selectedTenantId.value||!adminExperiencePage.value?.version)return;loading.value=true;errorMessage.value='';successMessage.value='';try{const v=adminExperiencePage.value.version;const saved=await apiPost<{version_id:string}>(`/platform/tenant-management/${selectedTenantId.value}/experience/pages/${adminExperienceSurface.value}/draft`,{html:v.html,template_key:adminExperiencePage.value.page?.template_key||null,bindings_values:adminExperienceBindings.value,theme:adminExperienceTheme.value,metadata:v.metadata||{},label:'Edição via Control Plane'},token());if(publish)await apiPost(`/platform/tenant-management/${selectedTenantId.value}/experience/pages/${adminExperienceSurface.value}/publish`,{version_id:saved.version_id},token());successMessage.value=publish?'Experiência salva e publicada pelo Control Plane.':'Rascunho salvo pelo Control Plane.';await loadAdminExperiencePage()}catch(error){errorMessage.value=describeError(error,'Falha ao salvar experiência.')}finally{loading.value=false}}
async function uploadAdminBrandAsset(kind:'logo'|'logo-dark'|'icon'|'favicon'|'login-background',event:Event):Promise<void>{
  if(!selectedTenantId.value)return
  const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file)return
  loading.value=true;errorMessage.value='';successMessage.value=''
  try{const form=new FormData();form.append('file',file);const result=await apiPostForm<any>(`/platform/tenant-management/${selectedTenantId.value}/experience/branding/assets/${kind}`,form,token());adminExperienceBranding.value=result.manifest||adminExperienceBranding.value;successMessage.value='Arquivo de identidade atualizado pelo Control Plane.'}catch(error){errorMessage.value=describeError(error,'Falha no upload de identidade.')}finally{loading.value=false;input.value=''}
}
async function saveAdminBranding():Promise<void>{if(!selectedTenantId.value||!adminExperienceBranding.value)return;loading.value=true;try{const b=adminExperienceBranding.value;const payload={public_name:b.app?.public_name||'',slogan:b.app?.slogan||'',primary_color:b.theme?.colors?.primary||'#2563EB',secondary_color:b.theme?.colors?.secondary||'#0B0F1A',accent_color:b.theme?.colors?.accent||'#0AE1C0',background_color:b.theme?.colors?.background||'#FFFFFF',text_color:b.theme?.colors?.text||'#0B0F1A',font_family:b.theme?.font_family||'Sora, Inter, system-ui, sans-serif',settings:b.settings||{}};adminExperienceBranding.value=await apiPut(`/platform/tenant-management/${selectedTenantId.value}/experience/branding`,payload,token());successMessage.value='Identidade visual atualizada pelo Control Plane.'}catch(error){errorMessage.value=describeError(error,'Falha ao salvar identidade.')}finally{loading.value=false}}
function adminBindingEntries():Array<[string,any]>{const raw=adminExperiencePage.value?.version?.metadata?.bindings||{};const defs=raw.bindings&&typeof raw.bindings==='object'?raw.bindings:raw;return Object.entries(defs).filter(([key])=>!['schema','version'].includes(key))}
async function saveExperiencePolicy():Promise<void>{if(!selectedTenantId.value)return;loading.value=true;errorMessage.value='';successMessage.value='';try{const value=await apiPut<ExperiencePolicy>(`/platform/tenant-management/${selectedTenantId.value}/experience-policy`,{level:experienceLevel.value,apply_theme_to_console:experienceThemeConsole.value},token());experienceLevel.value=value.level;experienceThemeConsole.value=Boolean(value.apply_theme_to_console);successMessage.value='Política do ARGWS Visual Builder atualizada.'}catch(error){errorMessage.value=describeError(error,'Falha ao atualizar a política do Visual Builder.')}finally{loading.value=false}}
async function lifecycle(action:'suspend'|'restore'):Promise<void>{if(!selectedTenantId.value||!selectedTenant.value)return;const label=action==='suspend'?'suspender':'restaurar';if(!await confirmDialog({title:action==='suspend'?'Suspender tenant':'Restaurar tenant',message:`Deseja ${label} ${selectedTenant.value.name}?`,danger:action==='suspend',confirmLabel:action==='suspend'?'Suspender':'Restaurar'}))return;loading.value=true;errorMessage.value='';successMessage.value='';try{await apiPost(`/platform/tenants/${selectedTenantId.value}/${action}`,{},token());await loadTenants();await loadSnapshot();successMessage.value=action==='suspend'?'Tenant suspenso.':'Tenant restaurado.'}catch(error){errorMessage.value=describeError(error,`Falha ao ${label} tenant.`)}finally{loading.value=false}}
async function logicalDelete():Promise<void>{if(!selectedTenantId.value||!selectedTenant.value)return;if(!await confirmDialog({title:'Excluir tenant',message:`Excluir logicamente ${selectedTenant.value.name}? Os recursos serão preservados e o tenant poderá ser restaurado.`,danger:true,confirmLabel:'Excluir'}))return;loading.value=true;errorMessage.value='';successMessage.value='';try{await apiDelete(`/platform/tenants/${selectedTenantId.value}`,token());await loadTenants();await loadSnapshot();successMessage.value='Tenant excluído logicamente. Banco, storage e artefatos foram preservados.'}catch(error){errorMessage.value=describeError(error,'Falha ao excluir tenant.')}finally{loading.value=false}}

onMounted(()=>{syncAuthentication();sessionTimer=window.setInterval(syncAuthentication,800)})
onUnmounted(()=>{if(sessionTimer!==undefined)window.clearInterval(sessionTimer)})
</script>

<template>
  <div v-if="authenticated" class="tenant-manager-root">
    <button class="tenant-manager-trigger" type="button" @click="openManager"><span>▤</span><strong>Gerenciar tenant</strong></button>
    <div v-if="isOpen" class="tenant-manager-backdrop" @click.self="isOpen=false">
      <section class="tenant-manager-drawer" role="dialog" aria-modal="true" aria-label="Gerenciar tenant">
        <header><div><span class="tenant-manager-eyebrow">Control Plane</span><h2>Gerenciar tenant</h2><p>Operação administrativa, acesso, diagnóstico e ciclo de vida do cliente.</p></div><button class="tenant-manager-close" type="button" @click="isOpen=false">×</button></header>
        <div class="tenant-manager-selector"><label>Tenant</label><select v-model="selectedTenantId" :disabled="loading" @change="selectTenant"><option value="">Selecione</option><option v-for="tenant in tenants" :key="tenant.id" :value="tenant.id">{{tenant.name}} — {{tenant.slug}}</option></select></div>
        <p v-if="errorMessage" class="tenant-manager-error">{{errorMessage}}</p><p v-if="successMessage" class="tenant-manager-success">{{successMessage}}</p><p v-if="loading" class="tenant-manager-loading">Atualizando dados...</p>
        <template v-if="snapshot">
          <div class="tenant-manager-status"><div><span>Status</span><strong>{{snapshot.tenant.status}}</strong></div><div><span>Domínio</span><strong>{{snapshot.tenant.primary_hostname||'Pendente'}}</strong></div></div>
          <nav class="tenant-manager-tabs"><button :class="{active:section==='general'}" @click="section='general'">Geral</button><button :class="{active:section==='access'}" @click="section='access'">Acesso</button><button :class="{active:section==='experience'}" @click="section='experience';loadAdminExperience()">Visual Builder</button><button :class="{active:section==='logs'}" @click="section='logs'">Logs</button><button :class="{active:section==='lifecycle'}" @click="section='lifecycle'">Ciclo de vida</button></nav>

          <form v-if="section==='general'" class="tenant-manager-card" @submit.prevent="saveTenant"><div class="tenant-manager-title"><div><h3>Dados do tenant</h3><p>Edite os dados operacionais sem alterar os identificadores isolados.</p></div></div><label>Nome da empresa</label><input v-model="tenantName" minlength="2" maxlength="160" required/><label>Código do tenant</label><input :value="snapshot.tenant.slug" disabled/><small>{{snapshot.slug_note}}</small><label>Fuso horário</label><input v-model="tenantTimezone" maxlength="64" required/><button class="tenant-manager-primary" type="submit" :disabled="loading">Salvar dados</button></form>

          <section v-if="section==='access'" class="tenant-manager-card"><div class="tenant-manager-title"><div><h3>Usuário principal do tenant</h3><p>Atualize a conta administrativa e reenvie os dados de conexão diretamente pelo SMTP da plataforma.</p></div></div><template v-if="snapshot.principal_admin"><label>E-mail principal</label><input v-model="adminEmail" type="email" required/><label>Nome de exibição</label><input v-model="adminDisplayName" minlength="2" maxlength="160"/><label>Nova senha</label><input v-model="adminPassword" type="password" minlength="12" maxlength="128" autocomplete="new-password" placeholder="Deixe vazio para manter a senha atual"/><small>A senha atual não é recuperada. Ao definir ou gerar uma nova senha, todas as sessões anteriores são revogadas.</small><div class="tenant-manager-access-actions"><button class="tenant-manager-secondary" type="button" :disabled="loading" @click="savePrincipalAdmin">Salvar alterações</button><button class="tenant-manager-primary" type="button" :disabled="loading" @click="resendAccess(false)">Salvar e reenviar acesso</button><button class="tenant-manager-secondary accent" type="button" :disabled="loading" @click="resendAccess(true)">Gerar senha temporária e reenviar</button></div><div v-if="generatedPassword" class="tenant-manager-once"><strong>Senha temporária gerada</strong><code>{{generatedPassword}}</code><small>Ela é exibida apenas nesta operação. O valor não é gravado nos logs administrativos.</small></div></template><div v-else class="tenant-manager-warning"><strong>Administrador principal ainda não disponível.</strong><span>{{snapshot.principal_admin_error?.message||'Conclua ou repita o provisionamento do tenant.'}}</span></div></section>

          <section v-if="section==='experience'" class="tenant-manager-card"><div class="tenant-manager-title"><div><h3>ARGWS Visual Builder 2.4.0</h3><p>Defina quanto o cliente pode personalizar. O Control Plane mantém acesso administrativo independentemente deste nível.</p></div></div><label>Nível liberado ao tenant</label><select v-model="experienceLevel"><option value="blocked">Bloqueado — sem editor</option><option value="basic">Básico — textos, imagens e contatos</option><option value="design">Design — básico + cores e tipografia</option><option value="full">Completo — experiência, SEO e templates</option><option value="developer">Desenvolvedor — HTML/CSS/JS, assets e bindings</option></select><label class="tenant-manager-check"><input v-model="experienceThemeConsole" type="checkbox"/> <span>Permitir aplicar a identidade do template também ao Tenant Console</span></label><small>Landing e Agenda continuam páginas HTML completas. Login permanece nativo/white-label do Scheduler Pro.</small><button class="tenant-manager-primary" type="button" :disabled="loading" @click="saveExperiencePolicy">Salvar política</button></section>

          <section v-if="section==='experience'" class="tenant-manager-card"><div class="tenant-manager-title"><div><h3>Personalização pelo Control Plane</h3><p>Edite bindings e publique mesmo quando o editor do tenant estiver bloqueado.</p></div></div><label>Superfície</label><select v-model="adminExperienceSurface" @change="loadAdminExperiencePage"><option value="LANDING">Landing Page</option><option value="BOOKING">Agenda Pública</option></select><template v-if="adminExperiencePage?.version"><small>Template: {{adminExperiencePage?.page?.template_key||'custom'}}</small><div v-if="adminBindingEntries().length" class="tenant-manager-binding-grid"><label v-for="[key,def] in adminBindingEntries()" :key="key">{{def.label||key}}<input v-model="adminExperienceBindings[key]"/></label></div><div v-else class="tenant-manager-warning"><strong>Template sem bindings declarados.</strong><span>O HTML permanece preservado; a edição segura exige bindings v1.</span></div><div class="tenant-manager-access-actions"><button class="tenant-manager-secondary" type="button" @click="saveAdminExperience(false)">Salvar rascunho</button><button class="tenant-manager-primary" type="button" @click="saveAdminExperience(true)">Salvar e publicar</button></div></template><div v-else class="tenant-manager-warning"><strong>Página ainda não inicializada.</strong><span>Importe/aplique um Experience Package no tenant.</span></div></section>

          <section v-if="section==='experience'&&adminExperienceBranding" class="tenant-manager-card"><div class="tenant-manager-title"><div><h3>Identidade visual do cliente</h3><p>Branding central usado por Landing, Agenda, Login nativo e PWA.</p></div></div><label>Nome público</label><input v-model="adminExperienceBranding.app.public_name"><label>Slogan</label><input v-model="adminExperienceBranding.app.slogan"><div class="tenant-manager-color-grid"><label>Primária<input v-model="adminExperienceBranding.theme.colors.primary" type="color"></label><label>Secundária<input v-model="adminExperienceBranding.theme.colors.secondary" type="color"></label><label>Accent<input v-model="adminExperienceBranding.theme.colors.accent" type="color"></label></div><div class="tenant-manager-brand-files"><label>Logo claro<input type="file" accept="image/*,.svg" @change="uploadAdminBrandAsset('logo',$event)"></label><label>Logo escuro<input type="file" accept="image/*,.svg" @change="uploadAdminBrandAsset('logo-dark',$event)"></label><label>Ícone PWA<input type="file" accept="image/*,.svg" @change="uploadAdminBrandAsset('icon',$event)"></label><label>Favicon<input type="file" accept="image/*,.svg,.ico" @change="uploadAdminBrandAsset('favicon',$event)"></label><label>Fundo do Login<input type="file" accept="image/*" @change="uploadAdminBrandAsset('login-background',$event)"></label></div><button class="tenant-manager-primary" type="button" @click="saveAdminBranding">Salvar identidade</button></section>

          <TenantLogInspector v-if="section==='logs'" embedded :tenant-id="snapshot.tenant.id" :tenant-name="snapshot.tenant.name" :tenant-slug="snapshot.tenant.slug" :tenant-hostname="snapshot.tenant.primary_hostname||null"/>

          <section v-if="section==='lifecycle'" class="tenant-manager-card danger-zone"><div class="tenant-manager-title"><div><h3>Ciclo de vida</h3><p>Suspensão e exclusão padrão preservam os recursos e mantêm o diagnóstico disponível.</p></div></div><div class="tenant-manager-actions"><button v-if="snapshot.tenant.status!=='SUSPENDED'" type="button" :disabled="loading" @click="lifecycle('suspend')">Suspender</button><button v-if="['SUSPENDED','DELETED'].includes(snapshot.tenant.status)" type="button" :disabled="loading" @click="lifecycle('restore')">Restaurar</button><button v-if="snapshot.tenant.status!=='DELETED'" class="danger" type="button" :disabled="loading" @click="logicalDelete">Excluir tenant</button></div></section>
        </template>
      </section>
    </div>
  </div>
</template>

<style scoped>
.tenant-manager-root{position:relative;z-index:5000}.tenant-manager-trigger{position:fixed;right:22px;bottom:22px;display:flex;align-items:center;gap:9px;border:1px solid rgba(17,138,245,.45);border-radius:14px;background:#0b0f1a;color:#fff;padding:12px 16px;box-shadow:0 18px 50px rgba(2,6,23,.28);cursor:pointer;font:inherit}.tenant-manager-trigger span{display:grid;place-items:center;width:27px;height:27px;border-radius:8px;background:linear-gradient(135deg,#2563eb,#7c3aed);font-weight:800}.tenant-manager-trigger strong{font-size:13px}.tenant-manager-backdrop{position:fixed;inset:0;background:rgba(2,6,23,.64);backdrop-filter:blur(5px);display:flex;justify-content:flex-end;z-index:5100;overflow:hidden}.tenant-manager-drawer{width:min(900px,100%);height:100dvh;overflow-y:auto;overflow-x:hidden;overscroll-behavior:contain;box-sizing:border-box;background:#f8fafc;color:#0f172a;padding:24px;box-shadow:-24px 0 80px rgba(2,6,23,.28)}.tenant-manager-drawer>header{display:flex;gap:18px;align-items:flex-start;justify-content:space-between;margin-bottom:20px}.tenant-manager-drawer h2{margin:4px 0 5px;font-size:26px}.tenant-manager-drawer p{margin:0;color:#64748b;font-size:13px;line-height:1.5}.tenant-manager-eyebrow{font-size:11px;letter-spacing:.14em;text-transform:uppercase;font-weight:800;color:#2563eb}.tenant-manager-close{border:0;background:transparent;font-size:34px;line-height:1;color:#475569;cursor:pointer}.tenant-manager-selector,.tenant-manager-card{display:grid;gap:8px;background:#fff;border:1px solid #e2e8f0;border-radius:16px;padding:16px;margin-bottom:14px}.tenant-manager-selector label,.tenant-manager-card label{font-size:12px;font-weight:750;color:#334155}.tenant-manager-selector select,.tenant-manager-card input,.tenant-manager-card select{width:100%;box-sizing:border-box;border:1px solid #cbd5e1;border-radius:10px;background:#fff;color:#0f172a;padding:10px 11px;font:inherit}.tenant-manager-card input:disabled{background:#f1f5f9;color:#64748b}.tenant-manager